#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
扩充 EnglishMaster 内容:
1. articles.json: 50 → 120 篇 (每级 20 篇,新增 70 篇)
2. conversations.json: 50 → 120 段 (每级 20 段,新增 70 段)
3. 新建 video_lessons.json: 分级 YouTube 视频点击跳转学习
"""
import json
import os
import re

BASE = r'c:\GitHub上传\EnglishMaster\data'

def load(name):
    p = os.path.join(BASE, name + '.json')
    if not os.path.exists(p):
        return None
    with open(p, 'r', encoding='utf-8') as f:
        return json.load(f)

def save(name, data):
    p = os.path.join(BASE, name + '.json')
    with open(p, 'w', encoding='utf-8') as f:
        json.dump(data, f, ensure_ascii=False, indent=2)

